// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/git/TileFooter.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * A session tile's footer with its Git items, ported from the app's
 * TileStatusStrip, FooterGit, FooterWorktree and FooterPath
 * (src/grid/Canvas.tsx) and styled by its stylesheet (app.css). The app
 * reads every value live (git status, gh, the worktree's info); a scene
 * passes them in.
 */
import {
  ArrowDown,
  ArrowUp,
  CircleCheck,
  CircleDashed,
  CircleX,
  GitBranch,
  GitMerge,
  GitPullRequest,
  GitPullRequestCreateArrow,
  GitPullRequestDraft,
  Loader2,
  Send,
  TriangleAlert,
  type LucideIcon,
} from "lucide-react";

/** GitFolderStatus (src/serverApi.ts). */
export interface FooterGit {
  branch: string;
  detached?: boolean;
  dirty?: boolean;
  ahead?: number | null;
  behind?: number | null;
}

/** GitPullRequest (src/serverApi.ts), as gh reports it. */
export interface FooterPullRequest {
  number: number;
  state: "OPEN" | "MERGED" | "CLOSED";
  draft?: boolean;
  checks: "passing" | "failing" | "pending" | "none";
}

/** A linked worktree (useWorktreeInfo in src/worktreeLand.ts) and the footer's landing state. */
export interface FooterWorktreeInfo {
  base: string | null;
  /** The title of the task that started it, which lands it instead. */
  task?: string;
  busy?: "pr" | "merge";
  landed?: "pr" | "merge";
}

export interface TileFooterInfo {
  /** The tmux session (and window) the tile shows. */
  session: string;
  git?: FooterGit;
  pr?: FooterPullRequest | null;
  /** The branch has a web page (GitHub, GitLab, Bitbucket) to open. */
  web?: boolean;
  /** The other tiles whose agent is on this branch of this checkout. */
  shared?: string[];
  /** An agent runs in the tile, so failing checks can be sent to it. */
  agent?: boolean;
  sendingChecks?: boolean;
  isolating?: boolean;
  worktree?: FooterWorktreeInfo;
  /** The full folder, "~" for the home folder. */
  path?: string;
  started?: string;
}

/** compactPath (src/grid/compactPath.ts) on a path that already starts at "~". */
export function compactPath(path: string): string {
  const home = path === "~" || path.startsWith("~/");
  const rest = (home ? path.slice(1) : path).split("/").filter(Boolean);
  if (rest.length <= 2) return home ? ["~", ...rest].join("/") : `/${rest.join("/")}`;
  return `${home ? "~" : ""}/…/${rest.slice(-2).join("/")}`;
}

function gitTitle(git: FooterGit): string {
  const parts = [git.detached ? `Detached at ${git.branch}` : `Branch ${git.branch}`, git.dirty ? "uncommitted changes" : "clean"];
  if (git.ahead != null && git.behind != null) parts.push(`${git.ahead} to push, ${git.behind} to pull`);
  return parts.join(" · ");
}

const CHECKS: Record<"passing" | "failing" | "pending", { icon: LucideIcon; label: string }> = {
  passing: { icon: CircleCheck, label: "checks passing" },
  failing: { icon: CircleX, label: "checks failing" },
  pending: { icon: CircleDashed, label: "checks running" },
};

function GitItem({ info, git }: { info: TileFooterInfo; git: FooterGit }) {
  const shared = info.shared ?? [];
  const pr = info.pr && info.pr.state !== "CLOSED" ? info.pr : null;
  const target = !!pr || !!info.web;
  const check = pr && pr.state === "OPEN" && pr.checks !== "none" ? CHECKS[pr.checks] : null;
  const PrIcon = pr?.state === "MERGED" ? GitMerge : pr?.draft ? GitPullRequestDraft : GitPullRequest;
  const prLabel = pr ? `Pull request #${pr.number}${pr.state === "MERGED" ? " · merged" : pr.draft ? " · draft" : ""}${check ? ` · ${check.label}` : ""}` : "";
  const title = [gitTitle(git), prLabel, target ? (pr ? "Click to open the pull request" : "Click to open the branch in the browser") : ""].filter(Boolean).join("\n");
  return (
    <span className="tile-strip-git">
      {git.dirty ? (
        <button type="button" className="tile-strip-git-icon tile-strip-review" title="Uncommitted changes · click to review them" aria-label="Review uncommitted changes">
          <GitBranch size={11} aria-hidden="true" />
        </button>
      ) : (
        <span className="tile-strip-git-icon">
          <GitBranch size={11} aria-hidden="true" />
        </span>
      )}
      <button type="button" className="tile-strip-branch-btn" title={title} disabled={!target}>
        <code className="tile-strip-branch">{git.branch}</code>
        {git.ahead ? (
          <span className="tile-strip-ab" aria-label={`${git.ahead} to push`}>
            <ArrowUp size={9} strokeWidth={2.4} aria-hidden="true" />
            {git.ahead}
          </span>
        ) : null}
        {git.behind ? (
          <span className="tile-strip-ab" aria-label={`${git.behind} to pull`}>
            <ArrowDown size={9} strokeWidth={2.4} aria-hidden="true" />
            {git.behind}
          </span>
        ) : null}
        {pr ? (
          <span className={`tile-strip-pr ${pr.state === "MERGED" ? "is-merged" : ""}`} aria-label={prLabel}>
            <PrIcon size={10} aria-hidden="true" />
            {pr.number}
            {check ? <check.icon size={10} className={`tile-strip-check is-${pr.checks}`} aria-hidden="true" /> : null}
          </span>
        ) : null}
      </button>
      {pr && check && pr.checks === "failing" ? (
        <button
          type="button"
          className="tile-strip-ci-send"
          aria-label="Send failing checks to agent"
          title={
            info.agent
              ? "Send failing checks to agent\nSaves the failed CI logs to a file and asks this tile's agent to fix them"
              : "Send failing checks to agent\nNo agent running in this tile"
          }
          disabled={!info.agent || info.sendingChecks}
          aria-busy={info.sendingChecks || undefined}
        >
          {info.sendingChecks ? <Loader2 size={11} className="async-spinner" aria-hidden="true" /> : <Send size={10} aria-hidden="true" />}
        </button>
      ) : null}
      {shared.length ? (
        <button
          type="button"
          className="tile-strip-shared"
          aria-label="Another agent is on this branch. Move this session to its own worktree"
          title={`Also on ${git.branch}: ${shared.join(", ")}.\nTwo agents on one branch can overwrite each other's work. Click to start this tile's agent in its own worktree; this session keeps running.`}
          disabled={!info.agent || info.isolating}
          aria-busy={info.isolating || undefined}
        >
          {info.isolating ? <Loader2 size={11} className="async-spinner" aria-hidden="true" /> : <TriangleAlert size={11} aria-hidden="true" />}
        </button>
      ) : null}
    </span>
  );
}

function WorktreeItem({ git, worktree, hasPullRequest }: { git: FooterGit; worktree: FooterWorktreeInfo; hasPullRequest: boolean }) {
  const { base, task, busy, landed } = worktree;
  const branch = git.branch;
  const icon = (kind: "pr" | "merge", Icon: LucideIcon) =>
    busy === kind ? (
      <Loader2 size={11} className="async-spinner" aria-hidden="true" />
    ) : landed === kind ? (
      <CircleCheck size={11} className="tile-strip-check is-passing" aria-hidden="true" />
    ) : (
      <Icon size={11} aria-hidden="true" />
    );
  const viaTask = task ? `\nPart of the task "${task}": opens its land checks` : "";
  const prLabel = landed === "pr" ? "Pull request opened" : "Open pull request";
  const mergeLabel = landed === "merge" ? `Merged into ${base}` : `Merge into ${base}`;
  return (
    <span className="tile-strip-wt">
      {hasPullRequest ? null : (
        <button
          type="button"
          className="tile-strip-wt-action"
          aria-label={prLabel}
          disabled={busy !== undefined}
          aria-busy={busy === "pr" || undefined}
          title={`${prLabel}${viaTask || `\nPushes ${branch} and runs gh pr create --fill`}`}
        >
          {icon("pr", GitPullRequestCreateArrow)}
        </button>
      )}
      {base ? (
        <button
          type="button"
          className="tile-strip-wt-action"
          aria-label={mergeLabel}
          disabled={(!!git.dirty && !task) || busy !== undefined}
          aria-busy={busy === "merge" || undefined}
          title={
            viaTask
              ? `${mergeLabel}${viaTask}`
              : git.dirty
                ? `${mergeLabel}\nCommit or discard this worktree's changes first`
                : `${mergeLabel}\nMerges ${branch} in the main checkout after a confirmation`
          }
        >
          {icon("merge", GitMerge)}
        </button>
      ) : null}
    </span>
  );
}

/** The footer: the session, its Git item, the worktree actions, the folder and when it started. */
export function TileFooter({ info }: { info: TileFooterInfo }) {
  const { git, path, started, worktree } = info;
  const hasPullRequest = !!info.pr && info.pr.state !== "CLOSED";
  return (
    <div className="tile-strip">
      <span className="tile-strip-target" title="tmux session">
        {info.session}
      </span>
      {git ? <GitItem info={info} git={git} /> : null}
      {git && worktree && !git.detached ? <WorktreeItem git={git} worktree={worktree} hasPullRequest={hasPullRequest} /> : null}
      {path ? (
        <button type="button" className="tile-strip-path" title={`${path}\nClick to copy`} aria-label={`Copy folder path ${path}`}>
          <span aria-live="polite">{compactPath(path)}</span>
        </button>
      ) : null}
      {started ? (
        <time className="tile-strip-time" title="Session started">
          started {started}
        </time>
      ) : null}
    </div>
  );
}
